<?php
function page_accounts():void {
 $users=rows('SELECT u.*,s.legal_name,c.name coop_name,b.company_name FROM users u LEFT JOIN suppliers s ON s.id=u.supplier_id LEFT JOIN cooperatives c ON c.id=u.coop_id LEFT JOIN buyer_profiles b ON b.id=u.buyer_id ORDER BY u.id DESC');
 $s=rows('SELECT id,legal_name FROM suppliers ORDER BY legal_name');$c=rows('SELECT id,name FROM cooperatives ORDER BY name');$b=rows('SELECT id,company_name FROM buyer_profiles ORDER BY company_name');
 ?><div class="row g-4"><div class="col-xl-4"><div class="panel panel-pad"><h5>Tambah akun mitra/staf</h5><p class="helper">Super Admin membuat akun Koperasi Induk, Koperasi Anak, Driver, dan staf tambahan.</p><form method="post"><?=csrf_input()?><input type="hidden" name="action" value="create_user"><div class="mb-3"><?php field('Nama','name');?></div><div class="mb-3"><?php field('Email','email','email');?></div><div class="mb-3"><?php field('Password (minimal 8 karakter)','password','password','','required minlength="8"');?></div><div class="mb-3"><?php select_field('Role','role',['super_admin'=>'Super Admin','induk'=>'Admin Koperasi Induk','supplier'=>'PT Pemasok','coop'=>'Koperasi Anak','buyer'=>'Pembeli Industri','driver'=>'Driver'],'','required onchange="changeRole(this.value)"');?></div><div id="supplier-assoc" class="mb-3 d-none"><?php select_field('PT terkait','supplier_id',array_column($s,'legal_name','id'),'','');?></div><div id="coop-assoc" class="mb-3 d-none"><?php select_field('Koperasi terkait','coop_id',array_column($c,'name','id'),'','');?></div><div id="buyer-assoc" class="mb-3 d-none"><?php select_field('Pembeli terkait','buyer_id',array_column($b,'company_name','id'),'','');?></div><button class="btn btn-coco w-100">Buat akun</button></form></div></div><div class="col-xl-8"><div class="panel"><div class="panel-pad"><h5>Semua pengguna · <?=count($users)?></h5><p class="helper mb-0">Akun dinonaktifkan tanpa menghapus histori transaksi.</p></div><div class="table-responsive"><table class="table"><thead><tr><th>Pengguna</th><th>Peran</th><th>Entitas</th><th>Status</th><th>Tindakan</th></tr></thead><tbody><?php foreach($users as $v):?><tr><td><b><?=e($v['name'])?></b><div class="helper"><?=e($v['email'])?></div></td><td><?=e($v['role'])?></td><td><?=e($v['legal_name']??$v['coop_name']??$v['company_name']??'—')?></td><td><?=((int)$v['is_active'])?'<span class="badge text-bg-success">Aktif</span>':'<span class="badge text-bg-secondary">Nonaktif</span>'?></td><td><?php if($v['id']!=$_SESSION['uid'])action_form('toggle_user',(int)$v['id'],(int)$v['is_active']?'Nonaktifkan':'Aktifkan','btn-outline-secondary');?></td></tr><?php endforeach;?></tbody></table></div></div></div></div>
<script>function changeRole(role){['supplier','coop','buyer'].forEach(r=>document.getElementById(r+'-assoc').classList.toggle('d-none',r!==role))}</script>
<?php }
